pub fn HSD_Encrypt<'a>(ctx: &'a Ctx, data: Val<'a, u8>, len: i32) -> i32 {
    let __frame = ctx.stack_frame(0x20);
    let mut data = data;
    let mut len = len;
    let mut i: i32 = 0;
    if Handle::is_null(data) {
        return 1_i32.wrapping_neg();
    }
    fns::HSD_Checksum(
        ctx,
        Handle::add(data, 16_i32),
        len.wrapping_sub(16_i32),
        Handle::cast::<Addr<'a>>(data),
    );
    {
        i = 16_i32;
        'l1: while i < len {
            'c2: {
                inl_encryptAt_unfused(ctx, Handle::add(data, i));
            }
            i = i.wrapping_add(1);
        }
    }
    return 0_i32;
}

